func explorerColumns() []datatable.Column[explorerRow] {
	return []datatable.Column[explorerRow]{
		// No title and neither Less nor Search (Rule 125): the column carries a
		// glyph, so the filter stays on Name and Slug.
		datatable.IndicatorColumn(
			func(r explorerRow) indicator.State { return r.Activity },
			restIcon,
			iconStyle,
		),
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: colNameMin, Flex: 2,
			Cell:   func(r explorerRow) string { return r.node.Name },
			Less:   func(a, b explorerRow) bool { return strings.ToLower(a.node.Name) < strings.ToLower(b.node.Name) },
			Search: func(r explorerRow) string { return r.node.Name },
		},
		{
	Style lipgloss.Style
}

// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
// IconColumnWidth). It is the only way a view builds one. Only the first column
// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
func IndicatorColumn[T any](state func(T) indicator.State,
	rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
	c := Column[T]{
		Sizing: SizingFixed, MinWidth: IconColumnWidth,
		Indicator: state,
		Cell: func(item T) string {
			if rest == nil {
				return ""
			}
			return rest(item)
		},
	}
	if restStyle != nil {
		c.Style = restStyle
	}
	return c
}
